@triton.autotune(configs=[
    triton.Config({'XBLOCK': 256, 'YBLOCK': 1}, num_warps=4, num_stages=1),
    triton.Config({'XBLOCK': 128, 'YBLOCK': 1}, num_warps=8, num_stages=1),
    triton.Config({'XBLOCK': 128, 'YBLOCK': 2}, num_warps=8, num_stages=1),
    triton.Config({'XBLOCK': 64,  'YBLOCK': 1}, num_warps=8, num_stages=1),
    # ... (16 configs total varying XBLOCK in {64,128,256}, YBLOCK in {1,2,4,8}, num_warps in {2,4,8})
], key=['ynumel', 'xnumel'])
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    ...

grid = lambda meta: (cdiv(xnumel, meta['XBLOCK']), cdiv(ynumel, meta['YBLOCK']))
kernel[grid](in_ptr, out_ptr, ynumel, xnumel)  # no hardcoded XBLOCK/YBLOCK
